 staff:{name:'KOR ASASI',hp:260,speed:160,range:174,damage:15,rate:.9,color:'#dba580',skills:['Kor küresi','Don halkası','Meteor'],glyphs:['✦','❄','☄'],cd:[4.5,9,15]}
