let scoreTarget=null;
let mode=1,matchType='vs',chosen='blade',phase='idle',paused=false,actors=[],shots=[],zones=[],effects=[],floating=[],score=[0,0],clock=120,round=1,nextRound=0,toastTimer=0,shake=0,serial=0,respawns=[];
