function setupRound(){actors=Array.from({length:mode*2},(_,i)=>{const team=i%2,slot=Math.floor(i/2),point=spawnPoint(team,slot,mode),kind=i===0?chosen:['blade','bow','staff'][(round+i+1)%3];return actor(team,point.x,point.y,kind,i===0);});shots=[];zones=[];effects=[];floating=[];respawns=[];if(typeof resetObjectives==='function')resetObjectives();clock=90;input.target=null;input.selectedEnemy=null;input.down=false;phase='draft';paused=false;camera={x:actors[0].x,y:actors[0].y};openDraft();$('#banner').classList.add('hidden');$('#pause').textContent='Ⅱ';notify('RAUND '+round+' · Ekipmanını seç · 90 saniye');updateHud();}
function start(){if(typeof net!=='undefined'&&net.active){notify('Önce odadan ayrıl.');return;}if(!requirePlayerName())return;if(typeof versionStatus!=='undefined'&&versionStatus.dataset.state!=='ready'){notify(versionStatus.dataset.state==='checking'?'Sürüm kontrolü bitmeden maça girilemez.':'Oyun sürümün sunucuyla eşleşmiyor. Sürümü güncelle veya ev sahibinin güncellemesini bekle.');return;}score=[0,0];round=1;setupRound();$('#start').innerHTML='MAÇI YENİLE <span>↻</span>';canvas.focus({preventScroll:true});}
