document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(typeof net!=='undefined'&&net.active){notify('Mod değiştirmek için odadan ayrıl.');return;}if(phase==='fight'||phase==='between'||phase==='draft'){notify('Mod değiştirmek için maçtan çık.');return;}mode=Number(b.dataset.mode);document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));$('#modeHint').textContent=mode===1?'Düello · Bir bot rakip':mode+'v'+mode+' · '+(mode-1)+' bot takım arkadaşı ve '+mode+' rakip';});
document.querySelectorAll('[data-match-type]').forEach(b=>b.onclick=()=>{if(typeof net!=='undefined'&&net.active||['fight','between','draft'].includes(phase)){notify('Maç türünü değiştirmek için maçtan çık.');return;}matchType=b.dataset.matchType;document.querySelectorAll('[data-match-type]').forEach(x=>x.classList.toggle('selected',x===b));const hints={vs:'3 raundu ilk kazanan ekip maçı alır.',capture:'Kontrol noktasını tut, 1.000 puana ulaş; ölen oyuncu yeniden doğar.',domination:'Üç bölgeyi ele geçir; bölgeler üstünlük puanı üret.'};$('#matchTypeHint').textContent=hints[matchType];});
function chooseArenaSize(size){setArenaSize(size);document.querySelectorAll('[data-arena-size]').forEach(b=>b.classList.toggle('selected',b.dataset.arenaSize===arenaSize));const hint=$('#arenaHint'),name=$('#arena-name');if(hint)hint.textContent=arenaSize==='grand'?'Büyük arena · 1.800 × 1.400 alan · 24 engel':'Standart arena · 1.300 × 1.000 alan · 16 engel';if(name)name.textContent=arenaSize==='grand'?'BÜYÜK ARENA':'KÜL AVLUSU';if(typeof setArenaLayout==='function')setArenaLayout(arenaLayout);}
