function togglePause(){if(typeof net!=='undefined'&&net.active){input.down=false;return;}if(phase!=='fight'&&phase!=='between')return;paused=!paused;input.down=false;input.keys.clear();$('#pause').textContent=paused?'▶':'Ⅱ';if(paused)showBanner('MOLA','Arena seni bekler.','Devam etmek için ESC veya sağ üstteki oynat düğmesi.');else $('#banner').classList.add('hidden');}
