function mousePosition(e){const r=canvas.getBoundingClientRect();input.screen={x:e.clientX-r.left,y:e.clientY-r.top};return unproject(input.screen.x,input.screen.y);}
canvas.addEventListener('pointermove',e=>{input.mouse=mousePosition(e)});
function mouseCommand(button,point){if(phase!=='fight'||paused||!actors[0]||actors[0].hp<=0)return;input.mouse=point;if(button!==0&&button!==2)return;const enemy=actors.find(a=>a.team!==(actors[0]?.team||0)&&a.hp>0&&!(a.stealth>0&&(a.reveal||0)<=0)&&dist(a,point)<42);if(enemy)input.selectedEnemy=enemy;else if(button===2){input.selectedEnemy=null;input.down=false;}input.enemy=enemy||null;input.target=enemy?null:{x:clamp(point.x,-arenaBounds.x,arenaBounds.x),y:clamp(point.y,-arenaBounds.y,arenaBounds.y)};effects.push({kind:'ring',x:point.x,y:point.y,r:18,color:'#92eee0',life:.4,max:.4});}
canvas.addEventListener('pointerdown',e=>{canvas.focus({preventScroll:true});const point=mousePosition(e);const r=canvas.getBoundingClientRect();const enemy=actors.find(a=>a.team!==(actors[0]?.team||0)&&a.hp>0&&!(a.stealth>0&&(a.reveal||0)<=0)&&Math.hypot((project(a.x,a.y,42).x-(e.clientX-r.left))/(30*scale),(project(a.x,a.y,42).y-(e.clientY-r.top))/(48*scale))<1);mouseCommand(e.button,enemy?{x:enemy.x,y:enemy.y}:point);input.down=e.button===0&&phase==='fight'&&!paused&&!input.enemy;if(input.down&&canvas.setPointerCapture)canvas.setPointerCapture(e.pointerId);});
window.addEventListener('pointerup',()=>input.down=false);
