canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;const key=e.code;if(['Space','KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','KeyR','Escape'].includes(key))e.preventDefault();if(key==='Escape'&&!e.repeat){togglePause();return;}input.keys.add(key);if(!e.repeat&&phase==='fight'&&!paused){const index=['KeyQ','KeyW','KeyE','KeyR'].indexOf(key);if(index>=0)cast(actors[0],[0,3,1,2][index],input.mouse);}});
