function move(a,dx,dy){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/7));for(let j=0;j<steps;j++){a.x=clamp(a.x+dx/steps,-arenaBounds.x,arenaBounds.x);a.y=clamp(a.y+dy/steps,-arenaBounds.y,arenaBounds.y);for(const p of pillars){const d=dist(a,p),min=p.r+15;if(d<min){const angle=Math.atan2(a.y-p.y,a.x-p.x);a.x=p.x+Math.cos(angle)*min;a.y=p.y+Math.sin(angle)*min;}}}a.motion=1;a.walk+=Math.hypot(dx,dy)*.1;}
function restoreHealth(a,amount){if(!a||a.hp<=0)return 0;const value=Math.min(a.max-a.hp,Math.max(0,amount)*(matchType==='flagRace'?2:1));a.hp+=value;return value;}
function damage(a,n,source){if(a.hp<=0||a.invul>0)return;const dealt=Math.round((matchType==='flagRace'?2:1)*n*(source&&source.human&&(source.passive||build)==='assault'?1.15:1)*(a.shield>0?.55:1));a.hp=Math.max(0,a.hp-dealt);a.hit=.16;floating.push({x:a.x,y:a.y,text:String(dealt),color:a.team?'#ffd3a6':'#f5bba8',life:.8});if(a.human)shake=4;effects.push({kind:'spark',x:a.x,y:a.y,life:.25,max:.25,color:a.team?'#e9a272':'#9bdce0'});if(a.hp===0&&!a.laneRole){if(matchType!=='vs'){respawns[a.id]=5;notify(a.human?'Düştün. 5 saniye sonra yeniden doğacaksın.':'Oyuncu düştü · yeniden doğma bekleniyor.');}else notify(a.human?'Düştün. Takım arkadaşın savaşa devam edebilir.':(a.team?'Rakip saf dışı.':'Takım arkadaşın düştü.'));}}
function fire(a,angle,damageValue,speed=420,r=7,color='#ddbd76',splash=0,hitGroup=null){shots.push({x:a.x+Math.cos(angle)*24,y:a.y+Math.sin(angle)*24,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,team:a.team,owner:a,damage:damageValue,r,color,life:1.15,splash,hitGroup,visual:a.kind});}
function attack(a,target){if(!a||a.hp<=0||a.attack>0||phase!=='fight'||paused)return;const k=kits[a.kind],angle=Math.atan2(target.y-a.y,target.x-a.x);a.facing=angle;a.attack=k.rate;a.anim=.42;a.animMax=.42;if(a.kind==='blade'){effects.push({kind:'slash',x:a.x,y:a.y,angle,life:.22,max:.22,r:72,color:'#edce89'});for(const b of actors)if(b.team!==a.team&&b.hp>0&&dist(a,b)<k.range+15&&clearRoute(a,b,0)&&Math.cos(Math.atan2(b.y-a.y,b.x-a.x)-angle)>.25)damage(b,k.damage,a);}else{const before=shots.length;fire(a,angle,k.damage,a.kind==='bow'?520:450,a.kind==='bow'?4:8,a.kind==='bow'?'#e5d396':'#efae79');for(const shot of shots.slice(before)){shot.maxRange=k.range;shot.originX=a.x;shot.originY=a.y;shot.life=(k.range+shot.r)/Math.max(1,Math.hypot(shot.vx,shot.vy));}}}
function cast(a,i,target){if(typeof net!=='undefined'&&net.active){net.send({type:'cast',skill:i,aim:target});return;}if(!a||a.hp<=0||a.cd[i]>0||phase!=='fight'||paused)return;const k=kits[a.kind],passive=a.passive||build;a.cd[i]=(i===3?5:k.cd[i])*(a.human&&passive==='flow'?.85:1);let angle=Math.atan2(target.y-a.y,target.x-a.x);a.facing=angle;abilityVisual(a,i,target);
 if(a.human&&i===0){if(passive==='guard'){restoreHealth(a,8);effects.push({kind:'ring',x:a.x,y:a.y,r:45,color:'#beacf5',life:.5,max:.5});}if(passive==='flow'){for(const b of actors)if(b.team!==a.team&&dist(a,b)<220)b.slow=1;effects.push({kind:'ring',x:a.x,y:a.y,r:220,color:'#77e6db',life:.5,max:.5});}}

 if((a.human||a.gear)&&castEquipment(a,i,target,angle))return;
 if(i===3){effects.push({kind:'ring',x:a.x,y:a.y,r:25,color:'#a8ccc0',life:.3,max:.3});move(a,Math.cos(angle)*130,Math.sin(angle)*130);a.invul=.23;if(a.human){(a.control||input).target=null;(a.control||input).enemy=null;}return;}
 if(a.kind==='blade'){
  if(i===0){effects.push({kind:'slash',x:a.x,y:a.y,angle,r:137,life:.35,max:.35,color:'#ffe0a0'});for(const b of actors)if(b.team!==a.team&&b.hp>0&&dist(a,b)<143&&clearRoute(a,b,0)&&Math.cos(Math.atan2(b.y-a.y,b.x-a.x)-angle)>-.2)damage(b,29,a);}
  if(i===1){move(a,Math.cos(angle)*163,Math.sin(angle)*163);for(const b of actors)if(b.team!==a.team&&dist(a,b)<91){damage(b,16,a);b.slow=1.3;}effects.push({kind:'ring',x:a.x,y:a.y,r:85,color:'#e4bf7a',life:.4,max:.4});}
  if(i===2){a.shield=2.4;floating.push({x:a.x,y:a.y,text:'KALKAN',color:'#d4dba8',life:1});}
 }else if(a.kind==='bow'){
  if(i===0){const group=new Set();for(const spread of [-.17,0,.17])fire(a,angle+spread,25,530,5,'#ead59c',0,group);}
  if(i===1){move(a,-Math.cos(angle)*156,-Math.sin(angle)*156);a.invul=.25;fire(a,angle,12,500);}
  if(i===2)addZone(a,target,117,.85,36,'#e5c781',.8);
 }else{
  if(i===0)fire(a,angle,27,390,13,'#ffab6b',91);
  if(i===1){effects.push({kind:'ring',x:a.x,y:a.y,r:189,color:'#a8dbd7',life:.5,max:.5});for(const b of actors)if(b.team!==a.team&&dist(a,b)<189){damage(b,13,a);b.slow=2.2;}}
  if(i===2)addZone(a,target,130,1.15,48,'#f29a6b',1.2);
 }
}
function addZone(a,t,r,delay,n,color,slow){const d=dist(a,t),f=Math.min(1,429/Math.max(1,d));zones.push({x:clamp(a.x+(t.x-a.x)*f,-arenaBounds.x,arenaBounds.x),y:clamp(a.y+(t.y-a.y)*f,-arenaBounds.y,arenaBounds.y),r,delay,max:delay,damage:n,color,team:a.team,owner:a,slow,visual:a.kind,variant:a.human?(a.loadout||equipmentChoice[a.kind])[3]:0});}
function bot(a,dt){let enemies=actors.filter(b=>b.team!==a.team&&b.hp>0&&!(b.stealth>0&&(b.reveal||0)<=0));if(!enemies.length)return;enemies.sort((b,c)=>dist(a,b)-dist(a,c));const b=enemies[0],d=dist(a,b),angle=Math.atan2(b.y-a.y,b.x-a.x),k=kits[a.kind];a.facing=angle;let dx=0,dy=0;const desired=a.kind==='blade'?52:k.range-25;if(d>desired+25){dx=Math.cos(angle);dy=Math.sin(angle);}else if(d<desired-40){dx=-Math.cos(angle);dy=-Math.sin(angle);}else if(a.kind!=='blade'){dx=Math.cos(angle+Math.PI/2)*.55;dy=Math.sin(angle+Math.PI/2)*.55;}
 for(const p of pillars)if(dist(a,p)<p.r+55){const side=(a.id%2?1:-1);dx+=(a.y-p.y)*side*.025;dy-=(a.x-p.x)*side*.025;}
 for(const z of zones)if(z.team!==a.team&&dist(a,z)<z.r+25){dx+=(a.x-z.x)/(dist(a,z)||1)*2;dy+=(a.y-z.y)/(dist(a,z)||1)*2;}
 const len=Math.hypot(dx,dy);if(d>desired+25||!clearRoute(a,b,0))followPath(a,b,(a.speed||k.speed)*(a.haste>0?1.35:1)*(a.slow>0?.45+.55*(a.accessory?.tenacity||0):1)*dt*.82,dt);else if(len)move(a,dx/Math.max(1,len)*(a.speed||k.speed)*(a.haste>0?1.35:1)*(a.slow>0?.45+.55*(a.accessory?.tenacity||0):1)*dt*.82,dy/Math.max(1,len)*(a.speed||k.speed)*(a.haste>0?1.35:1)*(a.slow>0?.45+.55*(a.accessory?.tenacity||0):1)*dt*.82);
 if(d<k.range+5&&clearRoute(a,b,0))attack(a,b);a.ai-=dt;if(a.ai<0){a.ai=.6+Math.random()*.8;if(a.kind==='blade'){if(d<100)cast(a,0,b);if(d>110&&d<230)cast(a,1,b);if(a.hp<a.max*.55)cast(a,2,b);}else{if(d<340)cast(a,0,b);if(d<140)cast(a,1,b);if(d<320)cast(a,2,b);}}
}
function matchGoal(){return 3;}
function endRound(team){if(team!==null)score[team]++;phase='between';input.down=false;input.enemy=null;input.selectedEnemy=null;nextRound=3;const finished=score.some(s=>s>=matchGoal());if(finished){phase='end';showBanner('MAÇ SONUCU',score[0]>=matchGoal()?'Arena senin.':'Bir sonraki raund senin.',score[0]+' — '+score[1]+' · Sonuç menüsünden devam edebilirsin.');}else notify(team===null?'Berabere · Yeni raund birazdan':(team===0?'Raund senin!':'Rakip raundu aldı.')+' · Yeni raund birazdan');updateHud();}
function playerStep(a,dt){const control=a.control||input;if(control.enemy&&(!actors.includes(control.enemy)||control.enemy.hp<=0))control.enemy=null;const enemy=control.enemy,goal=enemy||control.target;let dx=0,dy=0;if(goal){dx=goal.x-a.x;dy=goal.y-a.y;const d=Math.hypot(dx,dy),stop=enemy?(clearRoute(a,enemy,0)?kits[a.kind].range-10:20):3;if(d<=stop){dx=dy=0;if(!enemy)control.target=null;}else{const step=Math.min(d-stop,kits[a.kind].speed*(a.slow>0?.45:1)*dt);followPath(a,goal,step,dt);}}const aim=enemy||control.mouse;a.facing=Math.atan2(aim.y-a.y,aim.x-a.x);if(enemy&&dist(a,enemy)<=kits[a.kind].range&&clearRoute(a,enemy,0))attack(a,enemy);}
function update(dt){if(typeof net!=='undefined'&&net.active){net.frame(dt);return;}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}if(paused)return;for(const e of effects)e.life-=dt;effects=effects.filter(e=>e.life>0);for(const f of floating){f.life-=dt;f.y-=dt*15;}floating=floating.filter(f=>f.life>0);shake=Math.max(0,shake-dt*22);
 if(phase==='between'){nextRound-=dt;if(nextRound<=0){round++;setupRound();}return;}if(phase==='draft'){clock=Math.max(0,clock-dt);updateHud();if(clock<=0){notify('Seçim süresi doldu · Mevcut kuşanımla başlıyorsun.');confirmBuild();}return;}if(phase!=='fight')return;
 clock=Math.max(0,clock-dt);for(const a of actors){a.attack=Math.max(0,a.attack-dt);a.cd=a.cd.map(c=>Math.max(0,c-dt));for(const key of ['shield','invul','slow','hit','anim','motion'])a[key]=Math.max(0,(a[key]||0)-dt);if(a.hp<=0&&matchType!=='vs')respawnActor(a,dt);if(a.hp<=0)continue;if(a.human)playerStep(a,dt);else bot(a,dt);}
 for(const s of shots){if(s.homingTarget!==undefined){const target=actors.find(a=>a.id===s.homingTarget&&a.hp>0);if(target){const angle=Math.atan2(target.y-s.y,target.x-s.x),speed=Math.hypot(s.vx,s.vy);s.vx=Math.cos(angle)*speed;s.vy=Math.sin(angle)*speed;}}if(s.owner)s.owner.impactElement=s.element;const steps=Math.max(1,Math.ceil(Math.hypot(s.vx,s.vy)*dt/8));for(let j=0;j<steps&&s.life>0;j++){s.x+=s.vx*dt/steps;s.y+=s.vy*dt/steps;if(s.maxRange&&Math.hypot(s.x-s.originX,s.y-s.originY)>s.maxRange){s.life=0;break;}if(pillars.some(p=>{const dx=s.x-p.x,dy=s.y-p.y,r=p.r+s.r;return dx*dx+dy*dy<r*r;})){s.life=0;break;}const b=actors.find(a=>a.team!==s.team&&a.hp>0&&dist(a,s)<18+s.r);if(b){if(s.hitGroup?.has(b.id)){s.life=0;break;}s.hitGroup?.add(b.id);if(s.splash){for(const a of actors)if(a.team!==s.team&&a.hp>0&&dist(a,s)<s.splash)(typeof gearV3ProjectileDamage==='function'?gearV3ProjectileDamage(s,a):damage(a,s.damage,s.owner));effects.push({kind:'ring',x:s.x,y:s.y,r:s.splash,color:s.color,life:.4,max:.4});}else {const before=b.hp;(typeof gearV3ProjectileDamage==='function'?gearV3ProjectileDamage(s,b):damage(b,s.damage,s.owner));if(s.healOnHit&&b.hp<before&&s.owner?.hp>0)restoreHealth(s.owner,s.healOnHit);}if(s.slowOnHit&&b.hp>0&&b.invul<=0)b.slow=Math.max(b.slow,s.slowOnHit);s.life=0;}}s.life-=dt;if(s.owner)delete s.owner.impactElement;}shots=shots.filter(s=>s.life>0);
 for(const z of zones){if(z.owner)z.owner.impactElement=z.element;z.delay-=dt;if(z.delay<=0){for(const a of actors)if(a.team!==z.team&&a.hp>0&&dist(a,z)<z.r){(typeof gearV3ZoneDamage==='function'?gearV3ZoneDamage(z,a):damage(a,z.damage,z.owner));a.slow=z.slow;}effects.push({kind:'ability',style:z.element||'metal',element:z.element,x:z.x,y:z.y,r:z.r,color:z.color,life:.65,max:.65,angle:0});shake=5;}if(z.owner)delete z.owner.impactElement;}zones=zones.filter(z=>z.delay>0);
 if(matchType==='vs'){const alive=[actors.some(a=>a.team===0&&a.hp>0),actors.some(a=>a.team===1&&a.hp>0)];if(!alive[0]||!alive[1])endRound(alive[0]?0:alive[1]?1:null);else if(clock<=0){const sum=t=>actors.filter(a=>a.team===t).reduce((s,a)=>s+a.hp/a.max,0);endRound(Math.abs(sum(0)-sum(1))<.01?null:sum(0)>sum(1)?0:1);}}else stepObjectives(dt);updateHud();}
function updateHud(){const a=actors[0],k=kits[chosen],seconds=Math.max(0,Math.ceil(clock)),time=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'),draftTimer=$('#draft-timer');$('#blueScore').textContent=score[0];$('#redScore').textContent=score[1];$('#timer').textContent=time;$('#roundLabel').textContent=phase==='idle'?'3 GALİBİYETE ULAŞ':phase==='draft'?'EKİPMAN SEÇİMİ':'RAUND '+round+' / İLK 3 GALİBİYET';draftTimer.classList.toggle('hidden',phase!=='draft');if(phase==='draft')draftTimer.textContent='EKİPMAN SEÇİMİ · '+time;if(!a)return;$('#playerName').textContent=k.name;$('#hpText').textContent=Math.ceil(a.hp)+' / '+a.max;$('#hpFill').style.width=(a.hp/a.max*100)+'%';$('#status').textContent=a.hp<=0?'Saf dışı · Raundun bitmesini bekle':a.shield>0?'Demir irade · Hasar azaltma':a.slow>0?'Yavaşlatıldın':input.enemy?'Hedef kilitli · Yaklaş ve otomatik saldır':input.selectedEnemy?'Rakip seçili · Q/R ile nişan al':'Nişan al. Zamanlamanı seç.';document.querySelectorAll('.skill').forEach((b,i)=>{const c=b.querySelector('.cooldown');i=[0,3,1,2][i];c.classList.toggle('hidden',a.cd[i]<=0);c.textContent=a.cd[i].toFixed(1);});}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>{const s=project(p[0],p[1],p[2]||0);i?ctx.lineTo(s.x,s.y):ctx.moveTo(s.x,s.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function ellipse(x,y,r,color,alpha=1){const p=project(x,y);ctx.save();ctx.globalAlpha=alpha;ctx.beginPath();ctx.ellipse(p.x,p.y,r*scale,r*.53*scale,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.restore();}
function ring(x,y,r,color,width=2){const p=project(x,y);ctx.beginPath();ctx.ellipse(p.x,p.y,r*scale,r*.53*scale,0,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=width*scale;ctx.stroke();}
function draw(){ctx.clearRect(0,0,cw,ch);ctx.save();if(shake)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);const bg=ctx.createRadialGradient(cw*.5,ch*.5,0,cw*.5,ch*.5,cw*.7);bg.addColorStop(0,'#667055');bg.addColorStop(1,'#566c79');ctx.fillStyle=bg;ctx.fillRect(0,0,cw,ch);
 poly([[-arenaBounds.x-30,-arenaBounds.y-30,-15],[arenaBounds.x+30,-arenaBounds.y-30,-15],[arenaBounds.x+30,arenaBounds.y+30,-15],[-arenaBounds.x-30,arenaBounds.y+30,-15]],'#597081');
 poly([[-arenaBounds.x-15,-arenaBounds.y-15],[arenaBounds.x+15,-arenaBounds.y-15],[arenaBounds.x+15,arenaBounds.y+15],[-arenaBounds.x-15,arenaBounds.y+15]],'#819aa9','#d9b3af');
 if(typeof drawBattlefield==='function')drawBattlefield();
 drawGarden();drawSanctum();
 if(typeof drawEnvironmentRim==='function')drawEnvironmentRim();
 for(const z of zones){ellipse(z.x,z.y,z.r,z.color,.14);ring(z.x,z.y,z.r,z.team?'#e28b70':'#96d4d2');ring(z.x,z.y,z.r*(1-z.delay/z.max),z.color,3);drawZoneArt(z);}
 if(input.target&&phase==='fight'){const mark=input.target;ring(mark.x,mark.y,10+Math.sin(last*.009)*2,'#ead9a5',2);const q=project(mark.x,mark.y);ctx.strokeStyle='#fff0ba';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(q.x-4,q.y-7);ctx.lineTo(q.x,q.y-3);ctx.lineTo(q.x+4,q.y-7);ctx.stroke();}
 if(input.selectedEnemy&&input.selectedEnemy.hp>0&&!(input.selectedEnemy.stealth>0&&(input.selectedEnemy.reveal||0)<=0)&&phase==='fight')ring(input.selectedEnemy.x,input.selectedEnemy.y,29,'#ffb48b',3);
 if(typeof drawSkillTargeting==='function')drawSkillTargeting();
 if(typeof drawImpact==='function')for(const e of effects)if(e.kind==='stain')drawImpact(e);
 const preview=phase==='idle'?[{team:0,x:-205,y:0,kind:chosen,human:true,hp:kits[chosen].hp,max:kits[chosen].hp,walk:0,facing:0},{team:1,x:210,y:0,kind:'staff',hp:100,max:100,walk:0,facing:Math.PI}]:[];
 const visibleCover=p=>{const v=project(p.x,p.y,(p.h||0)*.5),margin=130*scale;return v.x>=-margin&&v.x<=cw+margin&&v.y>=-margin&&v.y<=ch+margin;};const entities=[...pillars.filter(visibleCover).map(p=>({depth:p.x+p.y,draw:()=>drawCover(p)})),...beacons.map(p=>({depth:p.x+p.y,draw:()=>drawBeacon(p)})),...(phase==='idle'?preview:actors).map(a=>({depth:a.x+a.y,draw:()=>drawChampion(a)}))];entities.sort((a,b)=>a.depth-b.depth).forEach(e=>e.draw());
 for(const s of shots)drawProjectile(s);
 for(const e of effects){if(e.kind==='stain')continue;ctx.globalAlpha=e.life/e.max;if(e.kind==='blood'||e.kind==='gear'||e.kind==='impact'){drawImpact(e);if(e.kind==='gear'&&typeof drawElemental==='function')drawElemental(e);}else if(e.kind==='ability'){drawAbility(e);if(typeof drawElemental==='function')drawElemental(e);}else if(e.kind==='ring')ring(e.x,e.y,e.r*(1-e.life/e.max*.45),e.color,4);else if(e.kind==='slash'){const p=project(e.x,e.y,18);ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale,scale*.53);ctx.beginPath();const angle=Math.atan2(Math.sin(e.angle)+Math.cos(e.angle),Math.cos(e.angle)-Math.sin(e.angle));ctx.arc(0,0,e.r,angle-1.1,angle+1.1);ctx.strokeStyle=e.color;ctx.lineWidth=9;ctx.stroke();ctx.restore();}else ring(e.x,e.y,30*(1-e.life/e.max),e.color,4);ctx.globalAlpha=1;}
 for(const f of floating){const p=project(f.x,f.y,85);ctx.globalAlpha=Math.min(1,f.life*2);ctx.font=`bold ${15*scale}px Inter,Arial`;ctx.fillStyle=f.color;ctx.textAlign='center';ctx.fillText(f.text,p.x,p.y);ctx.globalAlpha=1;}
 const vignette=ctx.createRadialGradient(cw/2,ch/2,ch*.25,cw/2,ch/2,cw*.7);vignette.addColorStop(0,'#0000');vignette.addColorStop(1,'#26394930');ctx.fillStyle=vignette;ctx.fillRect(0,0,cw,ch);ctx.restore();drawMinimap();}
const beacons=[{x:-590,y:-440},{x:590,y:440},{x:-590,y:440},{x:590,y:-440}];
function drawSanctum(){const pulse=.65+Math.sin(last*.0015)*.15;ctx.save();ctx.shadowBlur=14;ctx.shadowColor='#74dcc8';ring(0,0,170,'#94decc',2);ring(0,0,155,'#94decc55',1);ring(0,0,195,'#94decc33',1);for(let i=0;i<12;i++){const t=i*Math.PI/6,x=Math.cos(t)*181,y=Math.sin(t)*181;poly([[x-5,y],[x,y-7],[x+5,y],[x,y+7]],'#98dfc7');}ctx.globalAlpha=pulse;poly([[-36,0],[0,-36],[36,0],[0,36]],'#477f75','#bcf9df');poly([[-15,0],[0,-15],[15,0],[0,15]],'#c0e6ca');ctx.restore();for(const b of beacons){ellipse(b.x,b.y,78,'#cdae7040');ring(b.x,b.y,55,'#d8c59555');}for(let i=0;i<35;i++){const x=Math.sin(i*15.73)*620,y=Math.cos(i*31.21)*470,z=20+(Math.sin(last*.0007+i)+1)*23,p=project(x,y,z);ctx.globalAlpha=.2+(Math.sin(last*.002+i)+1)*.16;ctx.fillStyle='#e6d4a5';ctx.fillRect(p.x,p.y,2*scale,2*scale);}ctx.globalAlpha=1;}
function drawBeacon(b){poly([[b.x-20,b.y-20],[b.x+20,b.y-20],[b.x+20,b.y+20],[b.x-20,b.y+20]],'#344e49','#a3a982');poly([[b.x-12,b.y,8],[b.x,b.y,80],[b.x+12,b.y,8]],'#86d3c1','#c4ffee');const p=project(b.x,b.y,55);ctx.save();const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,55*scale);g.addColorStop(0,'#91ffe74a');g.addColorStop(1,'#91ffe700');ctx.fillStyle=g;ctx.fillRect(p.x-55*scale,p.y-55*scale,110*scale,110*scale);ctx.restore();}
function drawMinimap(){if(!actors.length)return;const w=126,h=96,x=cw-w-12,y=ch-h-12;ctx.save();ctx.fillStyle='#0d1b20df';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#657c74';ctx.strokeRect(x,y,w,h);for(const a of actors){ctx.fillStyle=a.hp<=0?'#53605b':a.human?'#ffffff':a.team?'#ed947b':'#83d4d0';ctx.beginPath();ctx.arc(x+(a.x+arenaBounds.x)/(arenaBounds.x*2)*w,y+(a.y+arenaBounds.y)/(arenaBounds.y*2)*h,a.human?3.5:2.5,0,Math.PI*2);ctx.fill();}ctx.font='8px Inter,Arial';ctx.fillStyle='#a4bcb1';ctx.textAlign='left';ctx.fillText(typeof mapNames!=='undefined'?mapNames[arenaLayout]:(arenaSize==='grand'?'BÜYÜK ARENA':'KÜL AVLUSU'),x+5,y-5);ctx.restore();}
function heldMovement(){if(!input.down||phase!=='fight'||paused||!actors[0]||actors[0].hp<=0)return;if(input.screen)input.mouse=unproject(input.screen.x,input.screen.y);input.enemy=null;input.target={x:clamp(input.mouse.x,-arenaBounds.x,arenaBounds.x),y:clamp(input.mouse.y,-arenaBounds.y,arenaBounds.y)};}
function frame(t){requestAnimationFrame(frame);if(!Number.isFinite(camera.x)||!Number.isFinite(camera.y))camera={x:0,y:0};const dt=Math.min((t-last)/1000||0,.09);last=t;heldMovement();update(dt);if(actors[0]){const follow=1-Math.exp(-dt*14),gap=dist(camera,actors[0]);camera.x+= (actors[0].x-camera.x)*(gap>260?1:follow);camera.y+=(actors[0].y-camera.y)*(gap>260?1:follow);}if(input.screen)input.mouse=unproject(input.screen.x,input.screen.y);try{draw();}catch(error){console.error('Arena render failed',error);if(typeof window.khRequestCanvasResize==='function')window.khRequestCanvasResize();}}
setKit();resize();requestAnimationFrame(frame);

const paths={assault:{name:'YIKIM',color:'#efbc98',icon:'blade',desc:'+%15 tüm hasar',detail:'Q: Güçlendirilmiş darbe. Tüm saldırıların daha güçlü.'},flow:{name:'AKIŞ',color:'#77e6db',icon:'flow',desc:'%15 kısa bekleme süresi',detail:'Q: Yakındaki rakipleri 1 sn yavaşlat.'},guard:{name:'MUHAFIZ',color:'#beacf5',icon:'guard',desc:'+%15 azami can',detail:'Q: Her kullanımda 8 can yenile.'}};
function art(type,color){const shapes={blade:'M26 69 L65 18 L75 24 L43 76 M24 60 L52 82 M30 76 L20 88',flow:'M18 40 Q42 10 77 32 L65 18 M78 58 Q53 89 22 65 L30 81 M25 46 L69 46 M31 56 L62 56',guard:'M50 14 L79 27 L75 58 Q68 77 50 87 Q32 77 25 58 L21 27 Z M50 30 L50 66 M35 47 L65 47',bow:'M26 18 Q82 47 26 82 L39 50 Z M21 50 L84 50 M72 39 L84 50 L72 61',staff:'M28 83 L65 27 M52 21 L70 12 L79 30 L62 39 Z M30 16 L33 24 M81 58 L89 58'};return '<svg viewBox="0 0 100 100" aria-hidden="true" style="--glow:'+color+'"><circle cx="50" cy="50" r="43"/><path d="'+shapes[type]+'"/></svg>';}
function openDraft(){const panel=$('#draft');panel.classList.remove('hidden');renderDraft();}
function confirmBuild(){if(typeof net!=='undefined'&&net.active){net.ready();return;}if(phase!=='draft')return;const old=actors[0];actors[0]=actor(0,old.x,old.y,chosen,true);if(old.scoreKey)actors[0].scoreKey=old.scoreKey;if(build==='guard'){actors[0].max=Math.round(actors[0].max*1.15);actors[0].hp=actors[0].max;}document.querySelectorAll('[data-class]').forEach(b=>b.classList.toggle('selected',b.dataset.class===chosen));setKit();$('#draft').classList.add('hidden');phase='fight';globalThis.window?.syncArenaFocus?.();clock=combatDuration();input.keys.clear();updateHud();notify(paths[build].name+' · Raund başladı!');canvas.focus({preventScroll:true});}
